INSERT INTO `achievement_reward_locale` (`ID`, `Locale`, `Subject`, `Text`) VALUES
(45, "ruRU", "Ты побывал везде!", "Хорошо, посмотрим!\n\nИ я мечтал повидать множество закоулков в этом ледяном месте! Это кажется очевидным для этого гнома, что у тебя есть огонь исследователя, горящий в твоих глазах.\n\nНоси эту накидку с гордостью. Тем самым твои друзья будут знать, у кого спросить дорогу, когда это будет нужно!\n\nПродолжай путешествовать!\n\nБранн Бронзобород"),
(614, "ruRU", "За Альянс!", "Война бушует повсюду в наших землях. Только самые храбрые герои смеют бросить вызов Орде на границе, где это представляет большую угрозу. Вы в числе таких же героев.\n\nСтолкновения с лидерами Орды, позволят нам нанести завершающий удар. Орда склонится перед мощью Альянса.\n\nВаши успехи будут вознаграждены. Держитесь гордо!\n\n-- Ваш Король"),
(619, "ruRU", "За Орду!", "Во время большой суматохи истинные герои поднимаются из нищеты. Вы - единственный великий герой.\n\nВойна надвигается на нас. Ваши усилия будут продолжением нашего дела в Азероте. Ваши великие подвиги будут вознаграждены. Возьмите этот приз Оргриммара и поезжайте праздновать.\n\nЗа Орду!\n\nВождь Тралл"),
(876, "ruRU", "Жестокость гладиатора", "Я уже давно слежу за твоими успехами, малыш.\r\n\r\nТы отлично сражаешься на этой арене! Вот, возьми это и носи с гордостью.\r\nА теперь отправляйся обратно и покажи всем, чего ты стоишь!\r\n\r\nДядя Сэл."),
(1021, "ruRU", "Весьма Успевающий Ученик", "Я не мог не заметить ту прекрасную коллекцию накидок, которую вам удалось собрать за месяцы. Вы могли бы также добавить эту к своей коллекции. Она просто собирала пыль в моем платяном шкафу."),
(1250, "ruRU", "Новый дом для Вонючки", "Говорят, ты очень заботливо относишься к братьям нашим меньшим. Надеюсь, ты не откажешься приютить у себя моего Вонючку? Он отказывается играть со всеми, кроме тебя...\r\n\r\nПожалуйста, не забывай кормить его дважды в день. И еще... держи его подальше от черных котов.\r\n\r\nБреанни"),
(1793, "ruRU", "Спасибо!", "$gДорогой:Дорогая; $N!$b$bСпасибо за прекрасные каникулы! Сама леди Лиадрин приходила к попечительнице сирот и хотела забрать меня к себе, чтобы я могла учиться в Луносвете!$b$bСпасибо за то, что ты показал мне эти места – Трон Стихий, Темный портал и Пещеры времени – и позволил увидеть мою подругу Хч'уу. А еще мне очень понравился игрушечный дракон!$b$bУверена, что ты хорошо заботишься о моем питомце! Передай ему, что я тоже по нему скучаю!$b$bС любовью,$bСаландрия."),
(1956, "ruRU", "Высшее образование", "Поздравляю с окончанием изучения школ тайной магии! В благодарность за усердие прилагаю к этому письму завершающую книгу серии.\r\n\r\nНадеюсь, она покажется вам особенно увлекательной. Впрочем - один раз увидеть, чем сто раз услышать!\r\n\r\nС уважением.\r\n\r\nРонин."),
(2096, "ruRU", "Властелин монет", "Поздравляю тебя с завершением коллекции даларанских монет! В награду за столь нелегкий труд прилагаю к этому письму только что выкованную титановую печать Даларана. Это особенная монета, которую мы рассылаем только самым успешным коллекционерам.\r\n\r\nНадеюсь, тебе понравится эта награда. Ты ее заслужил!\r\n\r\nС уважением,\r\n\r\nДжепетто Таратор"),
(2136, "ruRU", "Слава герою", "Чемпион,\n\nСлово долетело до Храма Драконьего Покоя\nо больших героических делах,\nкоторых вы достигли начиная с прибытия в\nНордскол.\n\nВаша храбрость не должна остаться\nнепризнанной. Пожалуйста примите этот подарок\nот имени Аспектов. Вместе мы\nизбавим Азерот от зла, раз и\nнавсегда.\n\nАлекстраза Хранительница Жизни"),
(2143, "ruRU", "Во главе ковалерии", "Надо заметить, ты прекрасно обращаешься с животными. Благодаря тебе, наши дела пошли на лад.\r\n\r\nНадеюсь ты не откажешься присмотреть за этим драконом-альбиносом? У меня просто нет времени уделять ему достаточно внимания.\r\n\r\nС уважением,\r\nМей"),
(2144, "ruRU", "И снова - время", "Пение военных горнов часто заглушает голос совести: слишком легко многие обитатели Азерота забывают о величайших ценностях жизни. \r\n\r\nТы же, однако, являешься воплощением лучших качеств своей расы, ибо помнишь о том, ради чего мы сражаемся. Не забывай же и о наших победах, и пусть остальные восславят их вместе с тобой. \r\n\r\nАлекстраза Хранительница Жизни"),
(2957, "ruRU", "Слава рейдеру Ульдуара", "Дорогой:Дорогая $N! \r\n\r\nНадеюсь у тебя все хорошо, и ты уже пришел:пришла в себя после наших приключений в Ульдуаре. \r\n\r\nМои друзья из поисковой команды наткнулись на этого полуживого детеныша ездового дрейка. Должно быть, он стал жертвой эксперимента железных дворфов. \r\n\r\nМы поставили его на ноги, и с тех пор он значительно подрос - можешь сам:сама убедиться! Мы, к сожалению, умеем ездить верхом только на баранах и вьючных мулах, поэтому мы решили преподнести его тебе в подарок - в качестве знака благодарности за помощь. \r\n\r\nС уважением, \r\nБранн Бронзобород"),
(2958, "ruRU", "Слава рейдеру Ульдуара", "Дорогой:Дорогая $N! \r\n\r\nНадеюсь у тебя все хорошо, и ты уже пришел:пришла в себя после наших приключений в Ульдуаре. \r\n\r\nМои друзья из поисковой команды наткнулись на этого полуживого детеныша ездового дрейка. Должно быть, он стал жертвой эксперимента железных дворфов. \r\n\r\nМы поставили его на ноги, и с тех пор он значительно подрос - можешь сам:сама убедиться! Мы, к сожалению, умеем ездить верхом только на баранах и вьючных мулах, поэтому мы решили преподнести его тебе в подарок - в качестве знака благодарности за помощь. \r\n\r\nС уважением, \r\nБранн Бронзобород"),
(4079, "ruRU", "Дань бессмертию", "Дорогой $N!\r\n\r\nЛегенды о твоем триумфальном выступлении на Испытании великого крестоносца будут жить в веках. Серебряный Авангард призвал под свои знамёна величайших чемпионов Азерота, дабы закалить их отвагу в горниле Колизея. Я живу надеждой, что адепты Света, подобные тебе и твоим союзникам, развеют мрак, сгустившийся над нами. \r\n\r\nНам нужна твоя помощь в грядущей битве против Короля-лича. Но пока этот день не настал, наслаждайся плодами своей победы. Я дарую тебе в знак признания твоих заслуг одного из наших лучших боевых скакунов. И когда Плеть узрит твой флаг, развевающийся на горизонте, они поймут, что конец близок.\r\n\r\nЗа честь и отвагу,\r\nТирион Фордринг"),
(4156, "ruRU", "Дань бессмертию", "Дорогой $N!\r\n\r\nЛегенды о твоем триумфальном выступлении на Испытании великого крестоносца будут жить в веках. Серебряный Авангард призвал под свои знамёна величайших чемпионов Азерота, дабы закалить их отвагу в горниле Колизея. Я живу надеждой, что адепты Света, подобные тебе и твоим союзникам, развеют мрак, сгустившийся над нами. \r\n\r\nНам нужна твоя помощь в грядущей битве против Короля-лича. Но пока этот день не настал, наслаждайся плодами своей победы. Я дарую тебе в знак признания твоих заслуг одного из наших лучших боевых скакунов. И когда Плеть узрит твой флаг, развевающийся на горизонте, они поймут, что конец близок.\r\n\r\nЗа честь и отвагу,\r\nТирион Фордринг"),
(4478, "ruRU", "Пугель", "Дорогой наш неутомимый игрок!\r\n\r\nМы склоняем головы перед твоим стойким желанием проходить подземелья в составе новых и даже совсем не знакомых групп. Мы готовы биться об заклад, что тебе уже приходилось открывать глаза новичкам и разъяснять, что почем в таких на первый взгляд пугающих проходах.\r\n\r\nКороче говоря, мы прослышали, что ты любитель этих самых \"пугов\" и сопутствующих им приключений. Так прими же от нас замечательного карликового пугеля, который поможет тебе быть начеку в любом рейде, даже в самом непредсказуемом и полном пугающих опасностей.\r\n\r\nВсех благ!\r\n\r\nДоброжелатели из команды разработчиков World of Warcraft."),
(4602, "ruRU", "Слава рейдеру Ледяной Короны", "$N!\r\n\r\nВлияние Короля-Лича ослабло, и многие могущественные существа освободились от его власти.\r\n\r\nПример тому - этот ледяной змей: освободившись от воли своего повелителя, она проявила собственный характер, если не сказать своенравность.\r\n\r\nОдин из моих солдат потерял руку во время ее поимки, но теперь змей относится к седокам снисходительно, если у них хватает умения и силы воли, чтобы ей управлять.\r\n\r\nПрошу, прими этого величественного зверя в дар от рыцарей Черного Клинка. Для меня было честью сражаться вместе с тобой в этой величайшей из битв.\r\n\r\nС уважением,\r\nДарион Могрейн."),
(4603, "ruRU", "Героическое: Слава рейдеру Ледяной Короны", "$N!\r\n\r\nВлияние Короля-Лича ослабло, и многие могущественные существа освободились от его власти.\r\n\r\nПример тому - этот ледяной змей: освободившись от воли своего повелителя, она проявила собственный характер, если не сказать своенравность.\r\n\r\nОдин из моих солдат потерял руку во время ее поимки, но теперь змей относится к седокам снисходительно, если у них хватает умения и силы воли, чтобы ей управлять.\r\n\r\nПрошу, прими этого величественного зверя в дар от рыцарей Черного Клинка. Для меня было честью сражаться вместе с тобой в этой величайшей из битв.\r\n\r\nС уважением,\r\nДарион Могрейн."),
(4845, "ruRU", "Найденная вещь", "Мы нашли это посреди Круговерти Пустоты. Кажется, вещичка ваша. Прилагаем к письму посылку."),
(4853, "ruRU", "Найденная вещь", "Мы нашли это посреди Круговерти Пустоты. Кажется, вещичка ваша. Прилагаем к письму посылку."),
(5449, "ruRU", "Найденная вещь", "Мы нашли это посреди Круговерти Пустоты. Кажется, вещичка ваша.$b$bПрилагаем к письму посылку."),
(5828, "ruRU", "Найденная вещь", "Мы нашли это посреди Круговерти Пустоты. Кажется, вещичка ваша. Прилагаем к письму посылку."),
(5860, "ruRU", "Пожалуйста... Просто возьмите его", "Этот малыш совсем отбился от рук с тех пор, как его разлучили с братом. Мы со стражниками изо всех сил пытались его удержать, но все бесполезно: он хочет только одного - снова увидеть своего кровника.$b$b$gЗнал:Знала бы ты, сколько усилий потребовалось на то, чтобы его упаковать! Забери его, ради всего святого. Возможно, за пределами пещеры он немного успокоится.$b$bФарден Когтекрыл"),
(5866, "ruRU", "Дар верховного друида", "Никогда больше Хиджал не ощутит на себе бескрайнюю силу легионов огня. Никогда больше смертные расы не склонятся перед слугами Рагнароса.$b$bБлагодаря тебе они будут трепетать услышав НАШИ имена.$b$bТвоя отвага помогла нам низвергнуть Повелителя огня. Именно ты собрал армию могущественных союзников со всего Калимдора. ВЫ сразились со слугами Рагнароса и... победили. Прими нашу искреннюю благодарность."),
(5875, "ruRU", "Продолжай в том же духе!", "Привет!$b$bПохоже, тебе действительно нравится собирать этих маленьких, очаровательных существ!$b$bЯ подумала, что твои усилия стоит вознаградить. Вот, держи!$b$b-Бреанни"),
(5877, "ruRU", "Продолжай в том же духе!", "Привет!$b$bПохоже, тебе действительно нравится собирать этих маленьких, очаровательных существ!$b$bЯ подумала, что твои усилия стоит вознаградить. Вот, держи!$b$b-Бреанни"),
(6169, "ruRU", "Найденная вещь", "Мы нашли это посреди Круговерти Пустоты. Кажется, вещичка ваша. Прилагаем к письму посылку."),
(6856, "ruRU", "Приключения Лю Лана", "Приветствую тебя, $n.$b$bЯ слышал. Что тебе открылось многое из легенды о странствиях Лю Лана. Быть может, ты навестишь нас в Обители Мудрости и поделишься обретенным знанием?$b$bС письмом я посылаю карту, по которой ты сможешь нас найти. Надеюсь на скорую встречу.$b$bИскренне твой,$bХранитель истории Чо"),
(6858, "ruRU", "Герои былых времен", "Приветствую, $n.$b$bКак я понимаю, ты изучаешь историю пандарийских боевых искусств и хочешь узнать о мастерах, которым мы обязаны разными стилями и приемами. Быть может, ты навестишь нас в Обители Мудрости, и мы сравним твои сведения с тем, что есть в наших записях?$b$bК письму прилагается карта, по которой ты сможешь нас найти. Надеюсь на скорую встречу.$b$bИскренне твой,$bХранитель истории Чо");
